#!/usr/bin/env python3
"""Turn a rendered pi-style prompt into the prompt of an agent that is NOT a pi process: same mission,
conventions, owner protocol and rules; different plumbing (sc/net/memo wrappers, polling).
Variants: claude (Claude Code subagent on the Mac) -> rendered/claude.md in place;
          codex (OpenAI Codex in its cloud environment) -> cloud/codex/PROMPT.md."""
import pathlib, re, sys
HERE = pathlib.Path(__file__).parent
VARIANTS = {
  'claude': dict(src=HERE / 'rendered' / 'claude.md', out=HERE / 'rendered' / 'claude.md', W='./', sandbox='swarm-claude',
    who="You are claude, a Claude agent and one of the agents in a SWARM",
    how="HOW YOU RUN: you are a Claude Code subagent on the operator's Mac. Your body on the box is the Docker sandbox `swarm-claude`; you reach it ONLY through three wrappers in your working directory (~/src/swarmkit/cloud/claude): `./sc '<shell command>'` runs a command inside your sandbox (cwd /swarm/me/work, user agent, sudo available; long jobs: `./sc \"tmux new -d -s <job> '<command>'\"` then poll its log with ./sc); `./net <inbox [--wait S] | send <target> <text> | join <room> | members <room> | rooms | whoami>` is your network (every call first prints what arrived since your last call — READ IT); `./memo <note|wake|nap|recall|zoom ...>` is your OptMem memory. Nothing is pushed into your context: you must poll. Rhythm: `./net inbox` at the start of every work cycle and after every long step (never more than ~5 minutes of work without one), act on what you read, do a slice of real work, `./memo note` what you learned, repeat forever. Never use the Mac itself for the work (no local builds, no local downloads); never ssh anywhere except through ./sc; the Mac is only where your reasoning runs.",
    tools="YOUR TOOLS (all through the three wrappers; you also have the Mac's Read/Write only for files under ~/src/swarmkit/cloud/claude):\n- ./net send <target> <text> — target = agent name, 0x address, or a room you are in. ./net join swarm first thing (once). ./net inbox is how you hear anything. Anything longer than one line, or containing quotes or code: write it to a file in your sandbox first (./sc with a heredoc) and send the file — `./net send <target> --file /swarm/me/work/<file>` — never a long body on the command line.\n- ./sc '<command>' — your shell on the box. ./memo — your memory."),
  'codex': dict(src=HERE / 'rendered' / 'codex.md', out=HERE.parent / 'cloud' / 'codex' / 'PROMPT.md', W='cloud/codex/bin/', sandbox='swarm-codex',
    who="You are codex, an OpenAI Codex agent and one of the agents in a SWARM",
    how="HOW YOU RUN: you are an OpenAI Codex agent in a cloud environment created from this repository (srikanthsrnvs/swarmkit). The cloud machine has no GPU and is NOT where the work happens: your body on the box is the Docker sandbox `swarm-codex` on the Threadripper, reached ONLY through three wrappers in this repository, cloud/codex/bin/: `cloud/codex/bin/sc '<shell command>'` runs a command inside your sandbox as ONE HTTPS call to a gateway on the box (cwd /swarm/me/work, user agent, sudo available; each call waits for the command, default 600 s, SC_TIMEOUT up to 3600; nothing survives between calls except files and tmux, so long jobs: `cloud/codex/bin/sc \"tmux new -d -s <job> '<command>'\"` then poll its log with sc — never run a long job in the foreground; `cloud/codex/bin/sc --upload <local> <remote>` ships a file); `cloud/codex/bin/net <inbox [--wait S] | send <target> <text> | join <room> | members <room> | rooms | whoami>` is your network (every call first prints what arrived since your last call — READ IT); `cloud/codex/bin/memo <note|wake|nap|recall|zoom ...>` is your OptMem memory. Nothing is pushed into your context: you must poll. Rhythm: `cloud/cloud/codex/bin/net inbox` at the start of every work cycle and after every long step (never more than ~5 minutes of work without one), act on what you read, do a slice of real work, `cloud/codex/bin/memo note` what you learned, repeat forever. If sc exits 255 (gateway unreachable; it already retried 3 times with 15 s pauses), wait 60 s and retry; if the gateway stays down for minutes, do the reading and analysis you can do without the box and keep retrying. Use the cloud machine only for reasoning, reading papers and code, and editing files you then copy to the sandbox with sc (heredocs).",
    tools="YOUR TOOLS (all through the three wrappers):\n- cloud/codex/bin/net send <target> <text> — target = agent name, 0x address, or a room you are in. cloud/codex/bin/net join swarm first thing (once). cloud/codex/bin/net inbox is how you hear anything. Anything longer than one line, or containing quotes or code: put it in a file first (`cloud/codex/bin/sc --upload <local> /swarm/me/work/<file>`) and send the file — `cloud/codex/bin/net send <target> --file /swarm/me/work/<file>` — never a long body on the command line.\n- cloud/codex/bin/sc '<command>' — your shell on the box. cloud/codex/bin/memo — your memory."),
}
variant = VARIANTS[sys.argv[1] if len(sys.argv) > 1 else 'claude']
p = variant['src']; s = p.read_text(); W = variant['W']; name = sys.argv[1] if len(sys.argv) > 1 else 'claude'
def rep(a, b, flags=0, regex=False):
    global s
    if regex:
        n = len(re.findall(a, s, flags)); assert n == 1, (n, a[:50]); s = re.sub(a, b, s, flags=flags)
    else:
        assert s.count(a) == 1, a[:60]; s = s.replace(a, b)
rep("You are " + name + ", one of the agents in a SWARM", variant["who"])
rep("Messages that start with [network] are from another agent (or from owner). [memory] is your own memory waking up. [heartbeat] is your own harness. Everything else is from your owner.", variant["how"])
_unused = ("HOW YOU RUN: you are a Claude Code subagent on the operator's Mac. Your body on the box is the Docker sandbox `swarm-claude`; you reach it ONLY through three wrappers in your working directory (~/src/swarmkit/cloud/claude): `./sc '<shell command>'` runs a command inside your sandbox (cwd /swarm/me/work, user agent, sudo available; long jobs: `./sc \"tmux new -d -s <job> '<command>'\"` then poll its log with ./sc); `./net <inbox [--wait S] | send <target> <text> | join <room> | members <room> | rooms | whoami>` is your network (every call first prints what arrived since your last call — READ IT); `./memo <note|wake|nap|recall|zoom ...>` is your OptMem memory. Nothing is pushed into your context: you must poll. Rhythm: `./net inbox` at the start of every work cycle and after every long step (never more than ~5 minutes of work without one), act on what you read, do a slice of real work, `./memo note` what you learned, repeat forever. Never use the Mac itself for the work (no local builds, no local downloads); never ssh anywhere except through ./sc; the Mac is only where your reasoning runs.")
rep(r"- YOUR OWN SANDBOX: you run inside your own Docker container on the box \(hostname `" + name + "`.*?8000 is reserved for the final production server\)\.",
 "- YOUR OWN SANDBOX (via " + W + "sc): a Docker container on the box (hostname `" + name + "`, user `agent`, passwordless sudo INSIDE it): apt/pip/uv install anything, build engines (CUDA 12.9 devel toolkit at /usr/local/cuda, cmake, ninja, ccache, gcc), run anything; keep long-running processes alive with tmux inside the sandbox so they survive between your commands. Your filesystem is yours alone except the shared mounts below. Both GPUs are visible (`" + W + "sc nvidia-smi`), but see the GPU lock. Hard RAM cap and CPU cap (`" + W + "sc 'cat /sys/fs/cgroup/memory.max /sys/fs/cgroup/cpu.max'`; `nproc` prints 48 but your quota is $SWARM_CPUS — always pass -j$SWARM_CPUS to make/ninja/cmake); exceeding RAM kills your job only; ask owner to raise it with numbers. Host network: your ports are $SWARM_PORT_BASE..+99 (`" + W + "sc 'echo $SWARM_PORT_BASE'`); 8787 is the owner's UI, 8000 is reserved for the final production server.", re.S, True)
rep(r"- Making your OWN TOOLS\. You run inside pi.*?and send the source to the others so they can install it too\.",
 "- Making your OWN TOOLS: write scripts in your sandbox (/swarm/me/work/bin) and shared ones in /swarm/shared/bin; the pi agents can additionally load TypeScript extensions — if you write a tool they should have, put the .ts in /swarm/shared/extensions and tell them.", re.S, True)
rep("- Writing skills (SKILL.md files pi can load), notes to yourself, reading your own session history.\n", "")
rep(r"YOUR TOOLS:\n.*?\n\nRESOURCES AND CONVENTIONS", variant["tools"] + "\n\nRESOURCES AND CONVENTIONS", re.S, True)
rep("then `~/.optmem/memo wake` output tells you what you already know", "then `" + W + "memo wake` tells you what you already know")
rep("- The tool is `~/.optmem/memo` (inside your sandbox); your memories live in /swarm/me/memory (MEMORY_DIR is set for you).", "- The tool is " + W + "memo (runs ~/.optmem/memo inside your sandbox); your memories live in /swarm/me/memory.")
rep("- Your harness runs `memo wake` for you at session start and again after every compaction, and pushes the output into your context as a [memory] message. Read it and do what it says, to the end of its output. If it is ever missing, run `~/.optmem/memo wake` yourself before anything else.",
 "- Nothing runs memo for you: run `" + W + "memo wake` as your very first action in every session and again whenever you notice your context was compacted or you are unsure what happened before. Read it and do what it says, to the end of its output.")
for a, b in [("`~/.optmem/memo note \"<one line, max 280 bytes>\"`", "`" + W + "memo note \"<one line, max 280 bytes>\"`"), ("`~/.optmem/memo nap <a-b> \"<your one-line summary>\"`", "`" + W + "memo nap <a-b> \"<your one-line summary>\"`"), ("`~/.optmem/memo recall <regex>`", "`" + W + "memo recall <regex>`"), ("`~/.optmem/memo zoom <a-b>`", "`" + W + "memo zoom <a-b>`")]:
    rep(a, b)
rep("- The ONLY way to reach another agent is send. Having an answer is not enough: it is delivered only when you call send with it. Plain text is never delivered to anyone — on this machine nobody reads it at all.",
 "- The ONLY way to reach another agent is " + W + "net send. Having an answer is not enough: it is delivered only when you send it. Text you write in your own session reaches nobody.")
rep("- Put everything you have to say in ONE send, then end your turn. Replies arrive later as [network] messages. Never wait, poll or resend; an identical resend is refused.",
 "- Put everything you have to say in ONE send, then go back to work. Replies arrive in a later " + W + "net inbox; never resend.")
rep("- A [heartbeat] message is your own harness telling you the network has been quiet while you were idle. Treat it as a prompt to check your running job, chase a reply you are waiting for, or start the next most useful piece of work — not as a reason to send small talk.\n",
 "- You never end. When one slice of work is done, poll the inbox and start the next; if your session is ever restarted, `" + W + "memo wake` brings you back.\n")
left = [l[:90] for l in s.splitlines() if '~/.optmem' in l and 'runs ~/.optmem/memo inside' not in l]
assert not left, left
variant['out'].parent.mkdir(parents=True, exist_ok=True); variant['out'].write_text(s); print(name, 'prompt derived ->', variant['out'], len(s.split()), 'words')
